(() => {
  // 自动定位主酒馆窗口（兼容 iframe 沙箱）
  let W = window;
  try { while (!W.document.getElementById('chat') && W !== W.parent) W = W.parent; } catch (e) {}
  const D = W.document, chat = D.getElementById('chat');
  if (!chat) return console.warn('[批注] 找不到 #chat');

  W.__anno?.();
  D.getElementById('anno-style')?.remove();
  const css = D.createElement('style');
  css.id = 'anno-style';
  css.textContent = `
    .anno{cursor:pointer;border-bottom:1.5px dashed var(--SmartThemeQuoteColor,#c9962f);}
    .anno-pop{position:fixed;z-index:99999;max-width:230px;padding:10px 13px;border-radius:14px;cursor:pointer;
      font-size:12px;line-height:1.6;letter-spacing:.01em;
      background-color:var(--SmartThemeBlurTintColor,#2b2b30);
      background-image:linear-gradient(var(--SmartThemeBlurTintColor,#2b2b30),var(--SmartThemeBlurTintColor,#2b2b30)),linear-gradient(var(--SmartThemeBlurTintColor,#2b2b30),var(--SmartThemeBlurTintColor,#2b2b30));
      -webkit-backdrop-filter:blur(14px) saturate(150%);backdrop-filter:blur(14px) saturate(150%);
      border:1px solid var(--SmartThemeBorderColor,rgba(255,255,255,.14));
      box-shadow:0 10px 32px var(--SmartThemeShadowColor,rgba(0,0,0,.45));
      color:var(--SmartThemeBodyColor,#eee);
      opacity:0;transform:translateY(5px) scale(.98);
      transition:opacity .2s cubic-bezier(.2,.7,.2,1),transform .2s cubic-bezier(.2,.7,.2,1);}
    .anno-pop.show{opacity:1;transform:none;}
    .anno-pop .row{margin:3px 0;}
    .anno-pop b{color:var(--SmartThemeQuoteColor,#b8860b);font-weight:600;}
    .anno-mono-name{font-weight:600;font-size:11px;color:var(--SmartThemeQuoteColor,#b8860b);margin-bottom:4px;letter-spacing:.04em;}
    .anno-mono{font-style:italic;opacity:.92;}`;
  D.head.appendChild(css);

  const RE = /\[\[(金句|高燃|转折)\]\]([\s\S]*?)\[\[网友\]\]([\s\S]*?)\[\[心声\]\]([\s\S]*?)\[\[\/\]\]/g;
  const ea = s => s.replace(/"/g, '&quot;');
  // 去掉酒馆渲染出的 <q> 等标签，只留纯文本
  const strip = (h) => { const d = D.createElement('div'); d.innerHTML = h; return (d.textContent || '').trim(); };
  const scan = () => D.querySelectorAll('#chat .mes_text').forEach(el => {
    if (!el.innerHTML.includes('[[')) return;
    el.innerHTML = el.innerHTML.replace(RE, (_, t, txt, c, m) =>
      `<span class="anno anno-${t}" data-c="${ea(strip(c))}" data-m="${ea(strip(m))}">${txt}</span>`);
  });
  scan();
  const obs = new MutationObserver(() => scan());
  obs.observe(chat, { childList: true, subtree: true });

  const esc = s => s.replace(/[&<>]/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;' }[c]));
  const charOf = (span) => span.closest('.mes')?.getAttribute('ch_name') || span.closest('.mes')?.querySelector('.name_text')?.textContent?.trim() || '内心独白';
  let pop = null, cur = null;
  const closePop = () => { pop?.remove(); pop = null; cur = null; };
  // 跟随：根据被标注文本的实时位置贴气泡
  const place = () => {
    if (!cur || !pop) return;
    const r = cur.span.getBoundingClientRect();
    pop.style.left = Math.max(8, Math.min(r.left, W.innerWidth - pop.offsetWidth - 8)) + 'px';
    pop.style.top = (r.bottom + 8) + 'px';
  };
  const show = (span, view) => {
    closePop();
    pop = D.createElement('div'); pop.className = 'anno-pop';
    if (view === 'c') {
      pop.innerHTML = (span.dataset.c || '').split('｜').map(s =>
        `<div class="row"><b>${esc(s.split(/：|:/)[0])}</b>：${esc(s.split(/：|:/).slice(1).join(''))}</div>`).join('');
    } else {
      pop.innerHTML = `<div class="anno-mono-name">${esc(charOf(span))}</div><div class="anno-mono">${esc(span.dataset.m || '')}</div>`;
    }
    D.body.appendChild(pop);
    cur = { span, view };
    place();
    requestAnimationFrame(() => pop.classList.add('show'));
  };
  let raf = 0;
  const reflow = () => { if (raf) return; raf = requestAnimationFrame(() => { raf = 0; place(); }); };
  D.addEventListener('scroll', reflow, true);
  W.addEventListener('resize', reflow);
  const onClick = (e) => {
    const span = e.target.closest('.anno');
    if (span) {
      e.stopPropagation();
      if (cur?.span !== span) show(span, 'c');
      else if (cur.view === 'c') show(span, 'm');
      else closePop();
    } else if (cur && e.target.closest('.anno-pop')) {
      e.stopPropagation();
      cur.view === 'c' ? show(cur.span, 'm') : closePop();
    } else {
      closePop();
    }
  };
  D.addEventListener('click', onClick, true);

  W.__anno = () => { obs.disconnect(); D.removeEventListener('click', onClick, true); D.removeEventListener('scroll', reflow, true); W.removeEventListener('resize', reflow); closePop(); css.remove(); };
})();
